from datasets import load_dataset
import json

ds = load_dataset('microsoft/lost_in_conversation', split='train')

# Find a code sample with shard >= 5
for i, row in enumerate(ds):
    if row['task'] == 'code' and len(row['shards']) >= 5:
        print('=== CODE SAMPLE (index', i, ') ===')
        d = {k: v for k, v in row.items() if v is not None and v != '' and v != []}
        # Truncate long fields
        if 'test' in d and len(str(d['test'])) > 500:
            d['test'] = str(d['test'])[:500] + '...[truncated]'
        if 'public_test_cases' in d and len(str(d['public_test_cases'])) > 300:
            d['public_test_cases'] = str(d['public_test_cases'])[:300] + '...[truncated]'
        if 'private_test_cases' in d and len(str(d['private_test_cases'])) > 300:
            d['private_test_cases'] = str(d['private_test_cases'])[:300] + '...[truncated]'
        print(json.dumps(d, indent=2, ensure_ascii=False))
        break

print()

